DECLARE @data TABLE (
 [Key] varchar(50), Action varchar(10), Name nvarchar(150), Category nvarchar(100),
 ActiveIngredient nvarchar(150), Ingredients nvarchar(max), Pack nvarchar(150),
 Unit nvarchar(30), Price decimal(18,2), Rx bit, Image nvarchar(255), Source nvarchar(500));
INSERT @data SELECT * FROM OPENJSON(@json) WITH (
 [Key] varchar(50) '$.key', Action varchar(10) '$.action', Name nvarchar(150) '$.name',
 Category nvarchar(100) '$.category', ActiveIngredient nvarchar(150) '$.activeIngredient',
 Ingredients nvarchar(max) '$.ingredients', Pack nvarchar(150) '$.pack', Unit nvarchar(30) '$.unit',
 Price decimal(18,2) '$.price', Rx bit '$.rx', Image nvarchar(255) '$.image', Source nvarchar(500) '$.source');
IF (SELECT COUNT(*) FROM @data WHERE Action='insert')<>50
    THROW 50002, N'Bộ dữ liệu không đủ 50 thuốc.', 1;
BEGIN TRY
 BEGIN TRANSACTION;
 DECLARE @stock bigint=(SELECT COALESCE(SUM(CONVERT(bigint,Stock)),0) FROM dbo.Batches);
 DECLARE @orders int=(SELECT COUNT(*) FROM dbo.Orders), @webOrders int=(SELECT COUNT(*) FROM dbo.WebOrders);
 DECLARE @oldPrices TABLE(Id int PRIMARY KEY, Price decimal(18,2));
 INSERT @oldPrices SELECT Id,Price FROM dbo.Medicines;
 INSERT dbo.Categories(Name,Description,IsActive,DisplayOrder)
 SELECT DISTINCT d.Category,N'Phân nhóm tham khảo danh mục thuốc Long Châu ngày 07/11/2026.',1,0
 FROM @data d WHERE NOT EXISTS(SELECT 1 FROM dbo.Categories c WITH(UPDLOCK,HOLDLOCK) WHERE c.Name=d.Category);
 DECLARE @supplier int=(SELECT MIN(Id) FROM dbo.Suppliers WITH(UPDLOCK,HOLDLOCK) WHERE Name=N'Chưa xác định nhà cung cấp');
 IF @supplier IS NULL
 BEGIN
  INSERT dbo.Suppliers(Name,Phone,Address,IsActive)
  VALUES(N'Chưa xác định nhà cung cấp','',N'Dữ liệu danh mục tham khảo; chọn nhà cung cấp thực tế trước khi nhập kho.',1);
  SET @supplier=CONVERT(int,SCOPE_IDENTITY());
 END;
 DECLARE @inserted TABLE(Id int, [Key] varchar(50));
 INSERT dbo.Medicines(CategoryId,SupplierId,BarCode,Name,ActiveIngredient,Unit,Price,IsPrescription,IsActive,IsSelling,PackagingSpec,DescriptionHtml,MainImageUrl)
 OUTPUT inserted.Id,inserted.BarCode INTO @inserted
 SELECT (SELECT MIN(c.Id) FROM dbo.Categories c WHERE c.Name=d.Category),@supplier,d.[Key],d.Name,d.ActiveIngredient,
 d.Unit,d.Price,d.Rx,CASE WHEN d.Price>0 THEN 1 ELSE 0 END,CASE WHEN d.Price>0 THEN 1 ELSE 0 END,d.Pack,
 N'<p><strong>Thành phần:</strong> '+REPLACE(REPLACE(REPLACE(d.Ingredients,N'&',N'&amp;'),N'<',N'&lt;'),N'>',N'&gt;')+
 N'</p><p><strong>Quy cách:</strong> '+d.Pack+
 N'</p><p>Đọc tờ hướng dẫn sử dụng và hỏi dược sĩ trước khi dùng.</p><p>Nguồn tham khảo: <a href="'+d.Source+
 N'">Nhà thuốc Long Châu</a> (07/11/2026).</p>',NULLIF(d.Image,N'')
 FROM @data d
 WHERE d.Action='insert'
 AND NOT EXISTS(SELECT 1 FROM dbo.Medicines m WITH(UPDLOCK,HOLDLOCK) WHERE m.BarCode=d.[Key] OR m.Name=d.Name);
 DECLARE @newCount int=@@ROWCOUNT, @enriched int;
 UPDATE m SET
  m.MainImageUrl=CASE WHEN NULLIF(LTRIM(RTRIM(m.MainImageUrl)),N'') IS NULL AND d.Image<>N'' THEN d.Image ELSE m.MainImageUrl END,
  m.ActiveIngredient=CASE WHEN NULLIF(LTRIM(RTRIM(m.ActiveIngredient)),N'') IS NULL THEN d.ActiveIngredient ELSE m.ActiveIngredient END,
  m.PackagingSpec=CASE WHEN NULLIF(LTRIM(RTRIM(m.PackagingSpec)),N'') IS NULL THEN d.Pack ELSE m.PackagingSpec END,
  m.DescriptionHtml=CASE WHEN NULLIF(LTRIM(RTRIM(m.DescriptionHtml)),N'') IS NULL THEN
   N'<p><strong>Thành phần tham khảo:</strong> '+d.Ingredients+
   N'</p><p>Đọc tờ hướng dẫn sử dụng và hỏi dược sĩ trước khi dùng.</p><p>Nguồn: <a href="'+d.Source+N'">Nhà thuốc Long Châu</a> (07/11/2026).</p>' ELSE m.DescriptionHtml END,
  m.IsPrescription=CASE WHEN d.Rx=1 THEN 1 ELSE m.IsPrescription END
 FROM dbo.Medicines m JOIN @data d ON d.Action='enrich' AND d.Name=m.Name;
 SET @enriched=@@ROWCOUNT;
 IF @stock<>(SELECT COALESCE(SUM(CONVERT(bigint,Stock)),0) FROM dbo.Batches)
 OR @orders<>(SELECT COUNT(*) FROM dbo.Orders)
 OR @webOrders<>(SELECT COUNT(*) FROM dbo.WebOrders)
 OR EXISTS(SELECT 1 FROM @oldPrices p JOIN dbo.Medicines m ON m.Id=p.Id WHERE m.Price<>p.Price)
    THROW 50003, N'Kiểm tra tồn kho/đơn hàng/giá cũ không đạt.',1;
 IF (SELECT COUNT(*) FROM @data d JOIN dbo.Medicines m ON d.[Key]=m.BarCode OR (d.Action='insert' AND d.Name=m.Name) WHERE d.Action='insert')<>50
    THROW 50004, N'Không đối chiếu được đầy đủ 50 thuốc mới.',1;
 IF OBJECT_ID(N'dbo.SystemConfig',N'U') IS NOT NULL
  UPDATE dbo.SystemConfig SET [Value]=CONVERT(nvarchar(255),COALESCE(TRY_CONVERT(bigint,[Value]),0)+1),UpdatedAt=GETDATE() WHERE [Key]=N'DataVersion';
 COMMIT TRANSACTION;
 SELECT @newCount AS NewMedicines,@enriched AS ExistingMedicinesMatched;
 SELECT m.Id,m.Name,m.Unit,m.Price,m.IsPrescription,m.MainImageUrl FROM dbo.Medicines m JOIN @data d ON d.[Key]=m.BarCode WHERE d.Action='insert' ORDER BY m.Id;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
